INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM200PFFQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 - 7x + 9 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-7)^2 - 4(2)(9) = 49 - 72 = -23$. Since the discriminant is negative, the equation has no real solutions, so the answer is $0$. The distractor $1$ reflects confusing a negative discriminant with a zero discriminant, which would yield exactly one repeated real root. The distractor $2$ assumes every quadratic has two real solutions without checking the discriminant. The distractor $3$ incorrectly treats the equation as if it were a cubic, confusing the degree with the number of solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM203K97B', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A store charges a flat fee of 23 dollars plus 6 dollars per hour for equipment rental. A second store charges no flat fee but 11 dollars per hour. For how many hours of rental is the total cost the same at both stores?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{17}$"},{"key":"B","text":"$\\frac{23}{5}$"},{"key":"C","text":"$\\frac{11}{6}$"},{"key":"D","text":"$\\frac{23}{6}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting costs equal: $23 + 6h = 11h$, which gives $23 = 5h$, so $h = \\frac{23}{5}$. The distractor $\\frac{23}{17}$ results from incorrectly adding the hourly rates ($6 + 11 = 17$) instead of subtracting them. The distractor $\\frac{11}{6}$ comes from setting up an incorrect ratio of the two hourly rates without accounting for the flat fee. The distractor $\\frac{23}{6}$ results from dividing the flat fee by only the first store''s hourly rate, ignoring the second store''s rate entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20Q03IO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains $11$ values. When the values are arranged in increasing order, the median is $37$. If the value $37$ is removed from the data set, which of the following must be true about the median of the remaining $10$ values?', NULL, $lyceon_json$[{"key":"A","text":"It is less than $37$."},{"key":"B","text":"It is equal to $37$."},{"key":"C","text":"It is greater than $37$."},{"key":"D","text":"It could be less than, equal to, or greater than $37$."}]$lyceon_json$::jsonb, 'D', NULL, E'With $11$ values, the median is the $6$th value, which is $37$. After removing one instance of $37$, there are $10$ values and the new median is the average of the $5$th and $6$th values in the sorted list. Depending on how many values equal $37$ and the distribution of the other values, the new median could be less than, equal to, or greater than $37$. For example, if the $5$th value is $35$ and the new $6$th value is $39$, the median is $37$; if both the $5$th and $6$th values are $37$, the median is $37$; if the $5$th value is $34$ and the new $6$th value is $38$, the median is $36$. Thus no single relationship must hold in all cases.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21Y1P8V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A store sells a jacket for $47$ dollars after applying a $6\\%$ sales tax to the pre-tax price. What is the pre-tax price, in dollars, rounded to the nearest cent?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '44.34', ARRAY['44.34'], E'If the pre-tax price is $p$, then $p \\times 1.06 = 47$. Solving: $p = \\frac{47}{1.06} \\approx 44.3396$, which rounds to $44.34$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24X4ZXD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = x^2 - 4x + 1$, and the function $g$ is defined by $g(x) = 2f(x - 3) + 7$. What are the coordinates of the vertex of the graph of $y = g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$(5, 1)$"},{"key":"B","text":"$(2, -3)$"},{"key":"C","text":"$(5, -3)$"},{"key":"D","text":"$(-1, 1)$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, rewrite $f(x) = x^2 - 4x + 1$ in vertex form by completing the square: $f(x) = (x - 2)^2 - 3$. The vertex of $f$ is at $(2, -3)$. The transformation $g(x) = 2f(x - 3) + 7$ shifts the graph of $f$ right by $3$ units, stretches vertically by a factor of $2$, and shifts up by $7$. The new vertex $x$-coordinate is $2 + 3 = 5$. The new vertex $y$-coordinate is $2(-3) + 7 = -6 + 7 = 1$. So the vertex of $g$ is $(5, 1)$. The distractor $(2, -3)$ gives the vertex of $f$ without applying any transformation. The distractor $(5, -3)$ correctly shifts the $x$-coordinate but fails to transform the $y$-coordinate. The distractor $(-1, 1)$ applies the horizontal shift in the wrong direction, subtracting $3$ from the $x$-coordinate instead of adding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25RU6CU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher surveys a random sample of 600 adults in a large city and finds that $37\\%$ support a proposed zoning change, with a margin of error of $3.9\\%$ at a $95\\%$ confidence level. A second researcher surveys a random sample of 150 adults from the same city and finds that $42\\%$ support the change, with a margin of error of $7.9\\%$ at the same confidence level. Which of the following conclusions is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The two surveys produce contradictory results about the population, so at least one must have used a biased sampling method."},{"key":"B","text":"Because the confidence intervals from the two surveys overlap, the results are consistent and the true proportion plausibly lies within both intervals."},{"key":"C","text":"The true proportion of adults who support the change is between $37\\%$ and $42\\%$."},{"key":"D","text":"The second survey is invalid because its margin of error exceeds $5\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'The first survey''s $95\\%$ confidence interval is $(33.1\\%, 40.9\\%)$ and the second survey''s is $(34.1\\%, 49.9\\%)$. These intervals overlap substantially, meaning the results are statistically consistent; different point estimates from different samples are expected due to sampling variability. The claim that the surveys are contradictory misunderstands that overlapping confidence intervals indicate compatibility, not conflict. Stating the true proportion is between $37\\%$ and $42\\%$ incorrectly treats the two point estimates as bounds rather than using the actual confidence intervals. The claim that a margin of error above $5\\%$ invalidates a survey has no statistical basis; margin of error depends on sample size and confidence level, not an arbitrary threshold.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25RXPJ0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'A student records the following quiz scores: $67$, $73$, $81$, $81$, $88$. What is the mean of these scores?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '78', ARRAY['78'], E'The sum of the scores is $67 + 73 + 81 + 81 + 88 = 390$. Dividing by $5$ gives a mean of $\\frac{390}{5} = 78$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25WL0GC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces $39$ identical bolts every $13$ minutes. At this constant rate, how many bolts does the factory produce in $1$ hour?', NULL, $lyceon_json$[{"key":"A","text":"$117$"},{"key":"B","text":"$156$"},{"key":"C","text":"$180$"},{"key":"D","text":"$195$"}]$lyceon_json$::jsonb, 'C', NULL, E'The factory produces $39$ bolts per $13$ minutes, which is $\\frac{39}{13} = 3$ bolts per minute. In $1$ hour ($60$ minutes), the factory produces $3 \\times 60 = 180$ bolts. The distractor $117$ results from multiplying $39 \\times 3$, counting only $3$ thirteen-minute intervals. The distractor $156$ comes from multiplying $39 \\times 4$, assuming exactly $4$ intervals fit in an hour. The distractor $195$ comes from multiplying $39 \\times 5$, treating one hour as $5$ intervals of $13$ minutes without accounting for the leftover $5$ minutes correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2653IWD', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{2(3x + 7)}{5} - 4 = 6$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Adding 4 to both sides gives $\\frac{2(3x + 7)}{5} = 10$. Multiplying both sides by 5 gives $2(3x + 7) = 50$. Dividing both sides by 2 gives $3x + 7 = 25$. Subtracting 7 from both sides gives $3x = 18$, so $x = 6$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26UTS3O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(-7, 3)$ and passes through the point $(-7, 15)$. Which of the following is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 7)^2 + (y - 3)^2 = 144$"},{"key":"B","text":"$(x - 7)^2 + (y + 3)^2 = 144$"},{"key":"C","text":"$(x + 7)^2 + (y - 3)^2 = 12$"},{"key":"D","text":"$(x + 7)^2 + (y - 3)^2 = 36$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(-7, 3)$ to $(-7, 15)$: $r = |15 - 3| = 12$. The standard form is $(x - h)^2 + (y - k)^2 = r^2$, giving $(x + 7)^2 + (y - 3)^2 = 144$. The distractor $(x - 7)^2 + (y + 3)^2 = 144$ uses incorrect signs in the center coordinates. The distractor with right side $12$ uses the radius instead of the radius squared. The distractor with right side $36$ results from computing $r = 6$ by halving the radius or miscalculating the distance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28WIBXX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The line $5x - 8y = 40$ is graphed in the $xy$-plane. A second line is perpendicular to this line and passes through the point $(3, -2)$. What is the $y$-coordinate of the point where the second line crosses the $y$-axis?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{-34}{5}$"},{"key":"B","text":"$\\frac{14}{5}$"},{"key":"C","text":"$\\frac{34}{5}$"},{"key":"D","text":"$\\frac{-14}{5}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Rewriting $5x - 8y = 40$ in slope-intercept form: $y = \\frac{5}{8}x - 5$, so the slope is $\\frac{5}{8}$. The perpendicular slope is $-\\frac{8}{5}$. Using point-slope form with $(3, -2)$: $y + 2 = -\\frac{8}{5}(x - 3)$, so $y = -\\frac{8}{5}x + \\frac{24}{5} - 2 = -\\frac{8}{5}x + \\frac{24}{5} - \\frac{10}{5} = -\\frac{8}{5}x + \\frac{14}{5}$. The $y$-intercept is $\\frac{14}{5}$. The distractor $\\frac{-34}{5}$ arises from using the original slope instead of the negative reciprocal and making a sign error in the calculation. The distractor $\\frac{34}{5}$ comes from using the positive reciprocal $\\frac{8}{5}$ instead of $-\\frac{8}{5}$. The distractor $\\frac{-14}{5}$ results from negating the correct answer due to a sign slip when distributing the perpendicular slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29LMGSV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population was $7{,}300$ at the start of $2020$ and $7{,}972$ at the start of $2022$. If the population grew by the same percent each year, which of the following is closest to the annual percent increase?', NULL, $lyceon_json$[{"key":"A","text":"$4.0\\%$"},{"key":"B","text":"$4.5\\%$"},{"key":"C","text":"$5.0\\%$"},{"key":"D","text":"$9.2\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the annual growth rate be $r$. Over $2$ years: $7{,}300(1 + r)^2 = 7{,}972$. So $(1 + r)^2 = \\frac{7{,}972}{7{,}300} \\approx 1.0921$, and $1 + r = \\sqrt{1.0921} \\approx 1.045$, giving $r \\approx 0.045$ or about $4.5\\%$. Verification: $7{,}300 \\times 1.045^2 = 7{,}300 \\times 1.092025 \\approx 7{,}972$. The distractor $4.0\\%$ comes from rounding down too aggressively or a computational slip. The distractor $5.0\\%$ results from estimating by halving the total increase and rounding up. The distractor $9.2\\%$ comes from computing the total percent increase $\\frac{672}{7{,}300} \\approx 9.2\\%$ without taking the square root to find the annual rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A1XB4D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid hemisphere of radius $r$ is placed flat-side down inside a cylinder whose base radius and height both equal $r$. What fraction of the cylinder''s volume is NOT occupied by the hemisphere?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{3}$"},{"key":"B","text":"$\\frac{2}{3}$"},{"key":"C","text":"$\\frac{1}{2}$"},{"key":"D","text":"$\\frac{1}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The cylinder has volume $V_{\\text{cyl}} = \\pi r^2 \\cdot r = \\pi r^3$. The hemisphere has volume $V_{\\text{hemi}} = \\frac{2}{3}\\pi r^3$. The unoccupied volume is $\\pi r^3 - \\frac{2}{3}\\pi r^3 = \\frac{1}{3}\\pi r^3$. The fraction of the cylinder not occupied is $\\frac{\\frac{1}{3}\\pi r^3}{\\pi r^3} = \\frac{1}{3}$. The distractor $\\frac{2}{3}$ represents the fraction occupied rather than unoccupied. The distractor $\\frac{1}{2}$ comes from incorrectly assuming the hemisphere fills exactly half the cylinder. The distractor $\\frac{1}{6}$ arises from an arithmetic error in computing the hemisphere volume fraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AKVMYX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $p$ passes through the points $(2, 13)$ and $(7, 43)$. What is the $y$-intercept of line $p$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1', ARRAY['1'], E'The slope is $m = \\frac{43 - 13}{7 - 2} = \\frac{30}{5} = 6$. Using point-slope form with $(2, 13)$: $y - 13 = 6(x - 2)$, which gives $y = 6x - 12 + 13 = 6x + 1$. Setting $x = 0$ yields $y = 1$, so the $y$-intercept is 1.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B5C23O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Two independent random samples are taken from the same population. Sample 1 has 250 respondents with a sample proportion of $0.41$ and a margin of error of $0.062$. Sample 2 has 1,000 respondents with a sample proportion of $0.38$ and a margin of error of $0.031$. Which of the following statements is best supported?', NULL, $lyceon_json$[{"key":"A","text":"Sample 1 is more likely to reflect the true population proportion because its sample proportion is higher."},{"key":"B","text":"Sample 2 provides a more precise estimate of the population proportion because its margin of error is smaller."},{"key":"C","text":"The two samples contradict each other, so neither can be trusted."},{"key":"D","text":"The true population proportion must be exactly $0.38$ because Sample 2 is larger."}]$lyceon_json$::jsonb, 'B', NULL, E'A larger sample size generally produces a smaller margin of error, yielding a more precise estimate. Sample 2, with 1,000 respondents and a margin of error of $0.031$, gives a confidence interval of $(0.349, 0.411)$, which is narrower than Sample 1''s interval of $(0.348, 0.472)$. The claim that Sample 1 is more likely to reflect the population proportion because its point estimate is higher confuses a higher sample proportion with greater accuracy. The claim that the two samples contradict each other is incorrect since their confidence intervals overlap. The statement that the true proportion must be exactly $0.38$ treats a sample statistic as if it were the population parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BZNB01', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution to the equation $\\sqrt{x + 7} = x - 5$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$9$"},{"key":"C","text":"$2$ and $9$"},{"key":"D","text":"$-7$ and $5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $x + 7 = x^2 - 10x + 25$, which simplifies to $x^2 - 11x + 18 = 0$. Factoring yields $(x - 9)(x - 2) = 0$, so $x = 9$ or $x = 2$. However, since squaring can introduce extraneous solutions, both must be checked. For $x = 9$: $\\sqrt{9 + 7} = \\sqrt{16} = 4$ and $9 - 5 = 4$, which is valid. For $x = 2$: $\\sqrt{2 + 7} = \\sqrt{9} = 3$ and $2 - 5 = -3$, so $3 \\neq -3$, which is extraneous. The only valid solution is $9$. The distractor $2$ results from not checking for extraneous solutions and selecting the smaller algebraic root. The distractor listing both $2$ and $9$ fails to reject the extraneous solution. The distractor $-7$ and $5$ comes from incorrectly setting each part of the original equation to zero separately.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CCMCDM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a service fee of 47 dollars plus 39 dollars for each hour of labor. If the total charge for a job is 281 dollars, which equation can be used to find $h$, the number of hours of labor?', NULL, $lyceon_json$[{"key":"A","text":"$39h + 47 = 281$"},{"key":"B","text":"$47h + 39 = 281$"},{"key":"C","text":"$39h - 47 = 281$"},{"key":"D","text":"$(39 + 47)h = 281$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total charge equals the fixed service fee plus the hourly rate times the number of hours: $39h + 47 = 281$. The distractor $47h + 39 = 281$ swaps the service fee and hourly rate, treating 47 as the per-hour cost. The distractor $39h - 47 = 281$ incorrectly subtracts the service fee instead of adding it. The distractor $(39 + 47)h = 281$ incorrectly treats the service fee as also being multiplied by the number of hours.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CPKAAQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles of a triangle measure $38°$ and $97°$. What is the measure, in degrees, of the third angle?', NULL, $lyceon_json$[{"key":"A","text":"$45°$"},{"key":"B","text":"$55°$"},{"key":"C","text":"$35°$"},{"key":"D","text":"$65°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of angles in a triangle is $180°$. The third angle is $180° - 38° - 97° = 45°$. The distractor $55°$ results from an arithmetic slip when subtracting ($180 - 38 = 142$, then $142 - 97$ miscalculated as $55$). The distractor $35°$ comes from subtracting in the wrong order or misreading $38°$ as $48°$. The distractor $65°$ reflects a misconception about the angle-sum property.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FAO3LH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher randomly assigns 120 students to two groups. Group A receives a new digital flashcard program for 6 weeks, while Group B uses traditional paper flashcards for the same period. At the end, Group A scores an average of 17 points higher on a vocabulary test. Which of the following conclusions is most justified?', NULL, $lyceon_json$[{"key":"A","text":"The digital flashcard program causes higher vocabulary scores, because the study used random assignment."},{"key":"B","text":"Students who prefer digital tools will always outperform students who prefer paper tools."},{"key":"C","text":"The difference is likely due to confounding variables since students chose their own group."},{"key":"D","text":"The results apply to all age groups and all types of learning, not just university students and vocabulary."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researcher randomly assigned students to the two groups, confounding variables are controlled for, and a causal conclusion is justified. The claim about students who prefer digital tools outperforming others overgeneralizes beyond what the study measured and introduces preference as a variable that was not part of the design. The assertion that the difference is due to confounding variables because students chose their own group is factually incorrect; the stem states that the researcher randomly assigned students. The claim that results apply to all age groups and types of learning goes far beyond the study''s population of university students and its focus on vocabulary.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G2UYY2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a building at point $C$ as $25°$. She then walks $40$ meters directly toward the building to point $B$, where the angle of elevation to $C$ is $50°$. Which of the following is closest to the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$31$"},{"key":"C","text":"$40$"},{"key":"D","text":"$52$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the height and $d$ be the horizontal distance from $B$ to the base. From point $B$: $\\tan(50°) = \\frac{h}{d}$, so $d = \\frac{h}{\\tan(50°)}$. From point $A$: $\\tan(25°) = \\frac{h}{d + 40}$, so $d + 40 = \\frac{h}{\\tan(25°)}$. Substituting: $\\frac{h}{\\tan(50°)} + 40 = \\frac{h}{\\tan(25°)}$, giving $40 = h\\left(\\frac{1}{\\tan(25°)} - \\frac{1}{\\tan(50°)}\\right)$. Using $\\tan(25°) \\approx 0.4663$ and $\\tan(50°) \\approx 1.1918$: $40 = h(2.1445 - 0.8391) = h(1.3054)$, so $h \\approx 30.6$, which is closest to $31$. The distractor $24$ results from an arithmetic slip in the subtraction step. The distractor $40$ assumes the height equals the walked distance. The distractor $52$ arises from incorrectly adding cotangent terms instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GQBRIT', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery company charges a flat fee of 19 dollars plus 4 dollars per pound for shipping. A customer has a budget of at most 83 dollars for shipping. Which inequality represents the number of pounds $p$ the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"$4p + 19 \\leq 83$"},{"key":"B","text":"$4p + 19 \\geq 83$"},{"key":"C","text":"$19p + 4 \\leq 83$"},{"key":"D","text":"$4p - 19 \\leq 83$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total shipping cost is the flat fee of 19 dollars plus 4 dollars per pound, giving $4p + 19$. Since the customer can spend at most 83 dollars, the inequality is $4p + 19 \\leq 83$. Using $\\geq$ instead of $\\leq$ reverses the budget constraint, incorrectly requiring the cost to be at least 83 dollars. Writing $19p + 4$ swaps the per-pound rate and the flat fee. Writing $4p - 19$ subtracts the flat fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HZEZ0Q', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 2x^2 - 9$. What is the value of $g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$27$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$ gives $g(3) = 2(3)^2 - 9 = 2(9) - 9 = 18 - 9 = 9$. The distractor $-9$ comes from ignoring the $2x^2$ term and returning only the constant $-9$. The distractor $27$ results from computing $3 \\times 9 = 27$ instead of $2 \\times 9 = 18$ before subtracting. The distractor $3$ arises from confusing the input value with the output value of the function.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I5BU7R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 voters in a city found that $53\\%$ plan to vote for Candidate A in the upcoming election. The margin of error for the survey is $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $53\\%$ of all voters in the city will vote for Candidate A."},{"key":"B","text":"Between $49\\%$ and $57\\%$ of all voters in the city are plausibly expected to vote for Candidate A."},{"key":"C","text":"Between $53\\%$ and $57\\%$ of all voters in the city will vote for Candidate A."},{"key":"D","text":"The survey is unreliable because the margin of error is too large."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $4\\%$ around a sample proportion of $53\\%$ means the plausible range for the true population proportion is $53\\% - 4\\% = 49\\%$ to $53\\% + 4\\% = 57\\%$. The claim that exactly $53\\%$ will vote for Candidate A treats the sample statistic as the exact population parameter, ignoring sampling variability. The range $53\\%$ to $57\\%$ adds the margin of error only in one direction instead of both. The claim that the survey is unreliable is unsupported; a $4\\%$ margin of error is a normal result for this sample size, not an indicator of unreliability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IMTE0P', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(2x - 7) + 5(x + 4)$?', NULL, $lyceon_json$[{"key":"A","text":"$11x - 1$"},{"key":"B","text":"$11x + 1$"},{"key":"C","text":"$11x - 41$"},{"key":"D","text":"$6x - 1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $6x - 21 + 5x + 20 = 11x - 1$. The distractor $11x + 1$ results from a sign error when computing $-21 + 20$ as $+1$ instead of $-1$. The distractor $11x - 41$ comes from incorrectly computing $-21 - 20$ instead of $-21 + 20$. The distractor $6x - 1$ omits the $5x$ term from the second group, reflecting incomplete distribution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J05P42', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 11x - 3$. What is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$74$"},{"key":"B","text":"$77$"},{"key":"C","text":"$80$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 7$: $f(7) = 11(7) - 3 = 77 - 3 = 74$. The distractor 77 results from computing $11 \\times 7$ but forgetting to subtract 3. The distractor 80 comes from adding 3 instead of subtracting it. The distractor 44 results from a miscalculation such as multiplying $11 \\times 4$ instead of $11 \\times 7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
