INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JUQQJ2', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $9x + 4y = 36$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 4)$"},{"key":"B","text":"$(0, 9)$"},{"key":"C","text":"$(4, 0)$"},{"key":"D","text":"$(0, 36)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting $x = 0$ in $9(0) + 4y = 36$ gives $4y = 36$, so $y = 9$. The $y$-intercept is $(0, 9)$. The distractor $(0, 4)$ confuses the coefficient of $y$ with the intercept value. The distractor $(4, 0)$ gives the $x$-intercept instead of the $y$-intercept. The distractor $(0, 36)$ uses the constant term without dividing by the coefficient of $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K5ILS9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{6x^2 + 7x - 3}{2x^2 + 7x + 6}$ can be simplified to $\\frac{ax + b}{cx + d}$ for integers $a$, $b$, $c$, and $d$, what is the value of $a + b + c + d$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$3$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $6x^2 + 7x - 3 = (3x - 1)(2x + 3)$. Factor the denominator: $2x^2 + 7x + 6 = (2x + 3)(x + 2)$. Cancel the common factor $(2x + 3)$ to get $\\frac{3x - 1}{x + 2}$. So $a = 3$, $b = -1$, $c = 1$, $d = 2$, and $a + b + c + d = 5$. The value 7 results from incorrectly keeping $b = 1$ instead of $b = -1$. The value 3 comes from only summing $a$ and $d$. The value 8 results from using the unfactored leading coefficients.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KBKI0I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A paint mixture requires $7$ parts blue pigment for every $3$ parts white pigment by volume. If a painter needs $4.5$ liters of white pigment for a project, how many liters of blue pigment are needed?', NULL, $lyceon_json$[{"key":"A","text":"$1.93$"},{"key":"B","text":"$9.5$"},{"key":"C","text":"$10.5$"},{"key":"D","text":"$11.5$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of blue to white is $7:3$. Setting up the proportion: $\\frac{\\text{blue}}{4.5} = \\frac{7}{3}$. Solving gives blue $= \\frac{7 \\times 4.5}{3} = \\frac{31.5}{3} = 10.5$ liters. The distractor $1.93$ arises from inverting the ratio, computing $\\frac{3 \\times 4.5}{7} \\approx 1.93$. The distractor $9.5$ comes from an arithmetic slip such as computing $\\frac{31.5}{3}$ as $9.5$ instead of $10.5$. The distractor $11.5$ comes from adding $7$ to $4.5$ instead of using the proportional relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KNE1BG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 13 red marbles, 9 blue marbles, and 3 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{22}$"},{"key":"B","text":"$\\frac{9}{25}$"},{"key":"C","text":"$\\frac{13}{25}$"},{"key":"D","text":"$\\frac{3}{25}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $13 + 9 + 3 = 25$. The probability of selecting a blue marble is $\\frac{9}{25}$. The answer $\\frac{9}{22}$ incorrectly excludes the green marbles from the total. The answer $\\frac{13}{25}$ gives the probability of red instead of blue. The answer $\\frac{3}{25}$ gives the probability of green instead of blue.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KX0H57', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $4$ cm and a height of $11$ cm. A cone has the same radius and the same height as the cylinder. What is the volume of the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{176\\pi}{3}$"},{"key":"B","text":"$176\\pi$"},{"key":"C","text":"$\\frac{44\\pi}{3}$"},{"key":"D","text":"$88\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(4)^2(11) = \\frac{176\\pi}{3}$. The distractor $176\\pi$ is the cylinder volume, applying $\\pi r^2 h$ without the $\\frac{1}{3}$ factor — a conceptual error confusing cone and cylinder formulas. The distractor $\\frac{44\\pi}{3}$ results from forgetting to square the radius ($\\frac{1}{3} \\cdot \\pi \\cdot 4 \\cdot 11$). The distractor $88\\pi$ comes from using $\\frac{1}{2}$ instead of $\\frac{1}{3}$ as the cone factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LTVJJW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $g$ is defined by $g(x) = ax + b$, where $a$ and $b$ are constants. If $g(3) = 29$ and $g(11) = 77$, what is the value of $g(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Using the two given values: $3a + b = 29$ and $11a + b = 77$. Subtracting the first equation from the second gives $8a = 48$, so $a = 6$. Substituting back into $3a + b = 29$: $18 + b = 29$, so $b = 11$. Therefore $g(x) = 6x + 11$, and $g(0) = 6(0) + 11 = 11$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M1YEQI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'grid_in', E'A circle has a diameter of $58$ inches. What is the radius of the circle, in inches?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '29', ARRAY['29'], E'The radius of a circle is half its diameter: $\\frac{58}{2} = 29$ inches.', NULL, NULL, 'draft', 1, 20, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N63ICY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A school fundraiser sells two types of tickets: adult tickets for 11 dollars each and student tickets for 7 dollars each. The organizers need to raise more than 539 dollars and can sell at most 61 tickets total. If $a$ represents the number of adult tickets and $s$ represents the number of student tickets, which system of inequalities models this situation?', NULL, $lyceon_json$[{"key":"A","text":"$11a + 7s > 539$ and $a + s \\leq 61$"},{"key":"B","text":"$11a + 7s \\geq 539$ and $a + s < 61$"},{"key":"C","text":"$7a + 11s > 539$ and $a + s \\leq 61$"},{"key":"D","text":"$11a + 7s > 539$ and $a + s \\geq 61$"}]$lyceon_json$::jsonb, 'A', NULL, E'Revenue from adult tickets is $11a$ and from student tickets is $7s$, so total revenue is $11a + 7s$. The phrase "more than 539 dollars" means strictly greater than, giving $11a + 7s > 539$. The phrase "at most 61 tickets" means $a + s \\leq 61$. Using $\\geq 539$ instead of $> 539$ misreads "more than" as "at least," and using $< 61$ for the ticket constraint misreads "at most" as "fewer than." Swapping the coefficients to $7a + 11s$ assigns the wrong price to each ticket type. Using $a + s \\geq 61$ reverses the ticket constraint, requiring at least 61 tickets instead of at most.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
