INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PLF78S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A line of best fit for a scatterplot relating outdoor temperature in degrees Fahrenheit ($F$) to the chirping rate of a species of cricket in chirps per second ($y$) is $y = 0.25F - 6$. If all temperatures are converted to degrees Celsius using $C = \\frac{5}{9}(F - 32)$, and a new line of best fit $y = mC + b$ is written in terms of the Celsius temperature, what is the value of $m$?', NULL, $lyceon_json$[{"key":"A","text":"$0.14$"},{"key":"B","text":"$0.25$"},{"key":"C","text":"$0.45$"},{"key":"D","text":"$0.50$"}]$lyceon_json$::jsonb, 'C', NULL, E'From $C = \\frac{5}{9}(F - 32)$, solving for $F$ gives $F = \\frac{9}{5}C + 32$. Substituting into $y = 0.25F - 6$: $y = 0.25\\left(\\frac{9}{5}C + 32\\right) - 6 = 0.25 \\cdot \\frac{9}{5}C + 0.25 \\cdot 32 - 6 = 0.45C + 8 - 6 = 0.45C + 2$. So $m = 0.45$. The distractor $0.14$ results from multiplying by $\\frac{5}{9}$ instead of $\\frac{9}{5}$: $0.25 \\times \\frac{5}{9} \\approx 0.14$. The distractor $0.25$ comes from assuming the slope does not change when the units are converted. The distractor $0.50$ results from incorrectly doubling the slope instead of multiplying by $\\frac{9}{5}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q3X4TL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{9x^2 - 16}{3x - 4}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 4$"},{"key":"B","text":"$9x - 4$"},{"key":"C","text":"$3x - 4$"},{"key":"D","text":"$9x + 16$"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator $9x^2 - 16$ is a difference of squares: $(3x)^2 - 4^2 = (3x - 4)(3x + 4)$. Dividing by $(3x - 4)$ gives $3x + 4$. The expression that tries to factor as $(9x - 4)$ misapplies the difference of squares pattern. The expression $3x - 4$ results from canceling without the second factor. The expression $9x + 16$ confuses the factored form with the original terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QH7K1B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one acute angle measures $37°$. If the side opposite this angle has length $19$, which expression gives the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{\\sin(37°)}$"},{"key":"B","text":"$\\frac{19}{\\cos(37°)}$"},{"key":"C","text":"$19 \\cdot \\sin(37°)$"},{"key":"D","text":"$19 \\cdot \\cos(37°)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the definition $\\sin(37°) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{19}{\\text{hypotenuse}}$, solving gives hypotenuse $= \\frac{19}{\\sin(37°)}$. Dividing by $\\cos(37°)$ confuses the ratio, since cosine relates the adjacent side to the hypotenuse, not the opposite. Multiplying $19$ by $\\sin(37°)$ inverts the relationship, giving a value smaller than the opposite side. Multiplying $19$ by $\\cos(37°)$ similarly misapplies the trigonometric ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
