INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QRN57O', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $4x - 9 > 19$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$6$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'D', NULL, E'Add 9 to both sides: $4x > 28$. Divide by 4: $x > 7$. Testing each option: $x = 5$ gives $4(5) - 9 = 11$, not greater than 19. $x = 7$ gives $4(7) - 9 = 19$, not strictly greater. $x = 6$ gives $4(6) - 9 = 15$, not greater than 19. $x = 10$ gives $4(10) - 9 = 31 > 19$, which satisfies the inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RV5XQ4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $PQR$, side $PQ$ is extended beyond $Q$ to point $S$, forming exterior angle $\\angle RQS$. The bisector of $\\angle RQS$ makes an angle of $54°$ with side $QR$. What is the sum of angles $\\angle P$ and $\\angle R$ of triangle $PQR$?', NULL, $lyceon_json$[{"key":"A","text":"$72°$"},{"key":"B","text":"$108°$"},{"key":"C","text":"$126°$"},{"key":"D","text":"$54°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The bisector of exterior angle $\\angle RQS$ divides it into two equal parts. Since the bisector makes a $54°$ angle with side $QR$, the exterior angle $\\angle RQS = 2 \\times 54° = 108°$. By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $\\angle P + \\angle R = 108°$. The distractor $72°$ comes from subtracting $108°$ from $180°$, confusing the interior angle at $Q$ with the requested sum. The distractor $126°$ comes from incorrectly computing $180° - 54°$ as the exterior angle. The distractor $54°$ results from misreading the question and reporting the bisector angle itself rather than the sum of the remote interior angles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S4LDGZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $14$ feet and a width of $9$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '126', ARRAY['126'], E'The area of a rectangle is length times width: $14 \\times 9 = 126$ square feet.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SKSEN5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A chemist prepares a solution by mixing compound $X$ and compound $Y$ in a mass ratio of $11:4$. She has $2.6$ kilograms of compound $X$ and $0.8$ kilograms of compound $Y$. She uses all of compound $Y$ and enough compound $X$ to maintain the required ratio. What mass of compound $X$, in kilograms, remains unused?', NULL, $lyceon_json$[{"key":"A","text":"$0.4$"},{"key":"B","text":"$0.6$"},{"key":"C","text":"$1.8$"},{"key":"D","text":"$2.2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using all $0.8$ kg of compound $Y$ with the $11:4$ ratio: $\\frac{X}{0.8} = \\frac{11}{4}$, so $X = \\frac{11 \\times 0.8}{4} = \\frac{8.8}{4} = 2.2$ kg of compound $X$ is needed. The unused amount is $2.6 - 2.2 = 0.4$ kg. The distractor $0.6$ comes from an arithmetic error in computing $\\frac{11 \\times 0.8}{4}$ as $2.0$ and then finding $2.6 - 2.0 = 0.6$. The distractor $1.8$ results from subtracting the mass of compound $Y$ from compound $X$ ($2.6 - 0.8 = 1.8$) rather than using the ratio. The distractor $2.2$ is the amount of compound $X$ used in the mixture, not the unused remainder.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SVJ46W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows data for $8$ cities, plotting average annual rainfall (in centimeters) on the $x$-axis and average number of sunny days per year on the $y$-axis. The line of best fit has the equation $y = -1.7x + 283$. According to this model, what is the predicted number of sunny days for a city with $90$ centimeters of annual rainfall?', NULL, $lyceon_json$[{"key":"A","text":"$130$"},{"key":"B","text":"$136$"},{"key":"C","text":"$153$"},{"key":"D","text":"$247$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 90$: $y = -1.7(90) + 283 = -153 + 283 = 130$. The distractor $136$ results from an arithmetic slip such as computing $-1.7 \\times 90 = -147$ instead of $-153$, giving $283 - 147 = 136$. The distractor $153$ comes from computing $1.7 \\times 90 = 153$ but ignoring the negative sign and not adding the intercept. The distractor $247$ comes from miscomputing $283 - 36$ by using only one digit of the product.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T1V80V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 68 commute by car, 47 commute by train, 31 commute by bus, and the rest bike or walk. Of those who commute by train, 19 also occasionally use the bus. If an employee who commutes by train is selected at random, what is the probability that this employee also occasionally uses the bus?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{47}$"},{"key":"C","text":"$\\frac{19}{78}$"},{"key":"D","text":"$\\frac{47}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the employee commutes by train, the sample space is the 47 train commuters. Of those, 19 also occasionally use the bus. The conditional probability is $\\frac{19}{47}$. The value $\\frac{19}{200}$ uses the total number of employees as the denominator rather than restricting to train commuters, which is the unconditional probability rather than the conditional one. The value $\\frac{19}{78}$ incorrectly adds $47 + 31 = 78$ as the denominator, combining train and bus commuters. The value $\\frac{47}{200}$ gives the probability of being a train commuter overall, not the conditional probability asked for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T68A1S', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution to the equation $x^2 + 2x - 48 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Factor the quadratic: $x^2 + 2x - 48 = (x + 8)(x - 6) = 0$. Setting each factor to zero gives $x = -8$ or $x = 6$. The positive solution is $6$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TCGQ6S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tests a new sleep aid by randomly assigning 300 volunteers to receive either the sleep aid or a placebo. Neither the volunteers nor the researchers administering the treatment know which group receives which. After 8 weeks, the group receiving the sleep aid reports an average of 43 more minutes of sleep per night compared to the placebo group, and the difference is statistically significant. However, a reviewer notes that all volunteers were recruited from a single hospital''s insomnia clinic. Which of the following best describes the implications of the reviewer''s concern?', NULL, $lyceon_json$[{"key":"A","text":"The causal conclusion is invalid because the study was not a randomized experiment."},{"key":"B","text":"The statistically significant result is likely a false positive because the sample came from one location."},{"key":"C","text":"The causal conclusion about the sleep aid's effect is supported by the study design, but the generalizability of the results to people without clinical insomnia is limited."},{"key":"D","text":"The study should have used a larger sample size to compensate for recruiting from a single hospital."}]$lyceon_json$::jsonb, 'C', NULL, E'The study is a double-blind randomized controlled experiment, which supports a causal conclusion about the sleep aid''s effect within the study population. However, because all participants were recruited from a single insomnia clinic, the results may not generalize to the broader population of people who do not have clinical insomnia. The claim that the causal conclusion is invalid because the study was not randomized contradicts the stem, which explicitly states random assignment. The suggestion that the significant result is likely a false positive because of the single-location sample confuses external validity (generalizability) with internal validity (whether the treatment effect is real within the study). The recommendation to increase sample size does not address the fundamental concern about the narrow recruitment population; a larger sample from the same restricted population still limits generalizability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UCNM5I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In the figure, two parallel lines are cut by a transversal. One of the angles formed measures $131°$. A triangle is formed such that one of its angles is the supplement of this $131°$ angle, and a second angle of the triangle measures $26°$. What is the measure, in degrees, of the third angle of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$105°$"},{"key":"B","text":"$23°$"},{"key":"C","text":"$49°$"},{"key":"D","text":"$75°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The supplement of $131°$ is $180° - 131° = 49°$. The triangle has angles $49°$, $26°$, and the unknown third angle. Since angles in a triangle sum to $180°$, the third angle is $180° - 49° - 26° = 105°$. The distractor $23°$ arises from confusing supplementary with complementary angles ($49° - 26°$). The distractor $49°$ results from stopping at the supplementary angle without completing the triangle calculation. The distractor $75°$ comes from incorrectly subtracting only $26°$ from $131°$ and treating $131° - 26° - 30° = 75°$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V60NRU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A retailer buys an item at wholesale for $w$ dollars and marks it up by $70\\%$ to set the retail price. During a clearance sale, the retail price is reduced by $35\\%$. The clearance price is what percent greater than the wholesale price $w$?', NULL, $lyceon_json$[{"key":"A","text":"$5\\%$"},{"key":"B","text":"$10.5\\%$"},{"key":"C","text":"$15\\%$"},{"key":"D","text":"$35\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The retail price is $1.70w$. After a $35\\%$ reduction, the clearance price is $1.70w \\times 0.65 = 1.105w$. This is $10.5\\%$ greater than $w$. The distractor $5\\%$ results from an arithmetic slip such as computing $0.70 \\times 0.65 = 0.455$ and misreading the result. The distractor $15\\%$ comes from partial reasoning, such as approximating $70\\% - 55\\%$ or another incorrect subtraction of percentages. The distractor $35\\%$ comes from subtracting $35\\%$ from $70\\%$ directly, treating successive percent changes as additive.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W1ELYI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health clinic notices that patients who attend weekly yoga classes have lower average blood pressure than patients who do not attend. A clinic administrator concludes that yoga classes cause lower blood pressure. Which of the following is the best reason this conclusion may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of patients may be too small to detect a difference."},{"key":"B","text":"The study is observational, so differences between the groups may be due to other factors rather than yoga itself."},{"key":"C","text":"Blood pressure measurements are unreliable."},{"key":"D","text":"The yoga classes were not held at the same time each week."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study because patients self-selected into yoga classes rather than being randomly assigned. Without random assignment, confounding variables (such as overall health consciousness, diet, or exercise habits) may explain the difference in blood pressure. The concern about sample size addresses statistical significance but does not explain why a causal conclusion is specifically problematic here. The claim that blood pressure measurements are unreliable is unsupported by anything in the scenario. The scheduling of yoga classes is irrelevant to whether a causal conclusion can be drawn from the study design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W7AGRX', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'For the system of equations $3x + 2y = 23$ and $5x - 2y = 17$, what is the value of $x + y$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$8$"},{"key":"C","text":"$9$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations gives $8x = 40$, so $x = 5$. Substituting into $3(5) + 2y = 23$ yields $2y = 8$, so $y = 4$. Therefore $x + y = 9$. The value $7$ results from stopping at $y = 4$ and confusing it with the sum, or reporting only one variable plus a miscalculation. The value $8$ comes from an arithmetic slip such as computing $2y = 6$ instead of $2y = 8$. The value $10$ arises from a sign error when adding the equations, such as getting $8x = 48$ by mishandling $-2y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WMPC20', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a group of 150 students, 83 study French, 61 study Spanish, and 27 study both French and Spanish. A student is selected at random. Given that the student studies at least one of these two languages, what is the probability that the student studies both?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{27}{150}$"},{"key":"B","text":"$\\frac{27}{117}$"},{"key":"C","text":"$\\frac{27}{83}$"},{"key":"D","text":"$\\frac{27}{144}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By inclusion-exclusion, the number of students studying at least one language is $83 + 61 - 27 = 117$. The conditional probability that a student studies both, given that the student studies at least one, is $\\frac{27}{117}$, which simplifies to $\\frac{9}{39} = \\frac{3}{13}$. The value $\\frac{27}{150}$ ignores the conditional restriction and uses the total group as the denominator. The value $\\frac{27}{83}$ uses only the French-studying group as the denominator, treating the condition as studying French rather than at least one language. The value $\\frac{27}{144}$ results from adding $83 + 61 = 144$ without subtracting the overlap, double-counting the students who study both.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X0WJFJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A researcher collects data on $6$ plants, recording the amount of fertilizer applied (in grams) and the height of the plant (in centimeters) after $4$ weeks. The data are: $(5, 14)$, $(9, 21)$, $(13, 27)$, $(17, 34)$, $(21, 40)$, $(25, 47)$. Using the line of best fit $y = 1.62x + 5.87$, what is the residual for the data point $(13, 27)$? Round your answer to the nearest hundredth.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.07', ARRAY['7/100', '0.07', '.07'], E'The predicted value at $x = 13$ is $y = 1.62(13) + 5.87 = 21.06 + 5.87 = 26.93$. The residual is the observed value minus the predicted value: $27 - 26.93 = 0.07$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y7584Z', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = -(x - 3)^2 + 17$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$-17$"},{"key":"C","text":"$17$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function $h(x) = -(x - 3)^2 + 17$ is a downward-opening parabola in vertex form $a(x - h)^2 + k$ with $a = -1$, vertex at $(3, 17)$. Since $a < 0$, the parabola opens downward, so the vertex gives the maximum value, which is $17$. The distractor $3$ confuses the $x$-coordinate of the vertex with the maximum output value. The distractor $-17$ results from incorrectly negating the constant term. The distractor $-3$ confuses the negation of the $x$-coordinate of the vertex with the answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZAPWL8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'In the $xy$-plane, a circle has equation $x^2 + y^2 - 10x + 6y - 2 = 0$. A line passes through the center of the circle and has slope $\\frac{3}{4}$. At what point does this line intersect the $y$-axis?', NULL, $lyceon_json$[{"key":"A","text":"$\\left(0, -\\frac{27}{4}\\right)$"},{"key":"B","text":"$\\left(0, \\frac{27}{4}\\right)$"},{"key":"C","text":"$(0, -3)$"},{"key":"D","text":"$\\left(0, \\frac{9}{4}\\right)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square: $(x^2 - 10x + 25) + (y^2 + 6y + 9) = 2 + 25 + 9 = 36$, giving $(x - 5)^2 + (y + 3)^2 = 36$. The center is $(5, -3)$. The line through $(5, -3)$ with slope $\\frac{3}{4}$ is $y - (-3) = \\frac{3}{4}(x - 5)$, so $y = \\frac{3}{4}x - \\frac{15}{4} - 3 = \\frac{3}{4}x - \\frac{27}{4}$. Setting $x = 0$: $y = -\\frac{27}{4}$, so the $y$-intercept is $\\left(0, -\\frac{27}{4}\\right)$. The distractor $\\left(0, \\frac{27}{4}\\right)$ drops the negative sign. The distractor $(0, -3)$ uses only the $y$-coordinate of the center. The distractor $\\left(0, \\frac{9}{4}\\right)$ results from an error in setting up the point-slope equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZBK476', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'A right triangle has legs of length $6$ and $11$. What is the area of this triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '33', ARRAY['33'], E'The area of a right triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height}$. Using the two legs as base and height: $\\frac{1}{2} \\times 6 \\times 11 = 33$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZFB72U', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $11x - 34 = 43$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Add 34 to both sides: $11x = 77$. Divide both sides by 11: $x = 7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW209MCWB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Ayana Elizabeth Johnson has argued that ocean conservation policies must account for the communities most affected by environmental ______ without their involvement, she contends, such policies risk deepening existing inequalities rather than alleviating them.', $lyceon_json$[{"key":"A","text":"degradation,"},{"key":"B","text":"degradation;"},{"key":"C","text":"degradation"},{"key":"D","text":"degradation, and"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence contains two independent clauses: one stating that ocean conservation policies must account for affected communities, and another beginning with "without their involvement, she contends" that explains the consequence. A semicolon correctly joins two independent clauses. A comma alone ("degradation,") would create a comma splice, since "without their involvement, she contends, such policies risk..." is an independent clause. Omitting punctuation entirely ("degradation") produces a run-on. The choice "degradation, and" is incorrect because the second clause begins with the adverbial phrase "without their involvement" and the parenthetical "she contends," making it a new independent assertion rather than a coordinated predicate; moreover, the resulting sentence would be structurally awkward and misleading.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20C7KVQ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The fruit bat Rousettus aegyptiacus is one of only a few bat species known to use echolocation produced by tongue clicking rather than laryngeal calls. Unlike the sophisticated sonar of insectivorous bats, which can resolve objects smaller than a millimeter, the fruit bat''s clicks generate only a crude spatial map. _Researchers believe this rudimentary system evolved as a supplement to the animal''s excellent night vision, not as a replacement for it._', $lyceon_json$[{"key":"A","text":"It provides a possible explanation for why the fruit bat's echolocation is less precise than that of other bats."},{"key":"B","text":"It challenges the assumption that all bats depend primarily on echolocation for navigation."},{"key":"C","text":"It introduces a new line of research into the origins of laryngeal echolocation."},{"key":"D","text":"It describes an experiment that tested the fruit bat's visual acuity."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence states that the rudimentary echolocation system evolved as a supplement to night vision, not a replacement, which explains why the system did not need to become highly precise — it serves a supporting role alongside vision. The choice claiming it challenges assumptions about bat navigation overreaches; the passage does not address what "all bats" depend on. The choice mentioning laryngeal echolocation origins misreads the text, which distinguishes tongue clicking from laryngeal calls but does not investigate the origins of the latter. The choice about a visual acuity experiment misreads the passage, which presents a hypothesis rather than describing an experiment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20MQNCI', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'The diplomat Marguerite Boucicaut was known for her ability to temper the inflammatory rhetoric of rival delegations without appearing to censor them. During the 1947 Lausanne negotiations, she would paraphrase aggressive proposals in softer language, preserving their substantive demands while stripping away provocative phrasing. Her colleagues credited this technique with preventing at least two walkouts during the conference''s most contentious sessions.', $lyceon_json$[{"key":"A","text":"harden"},{"key":"B","text":"moderate"},{"key":"C","text":"abandon"},{"key":"D","text":"provoke"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Boucicaut paraphrasing aggressive proposals in "softer language" and "stripping away provocative phrasing" while preserving substance, indicating that "temper" means moderate — to reduce the intensity of something. "Harden" is a meaning of "temper" in metallurgy (to strengthen metal by heating and cooling), but it contradicts the passage''s emphasis on softening rhetoric. "Abandon" implies giving up entirely, but the passage stresses that Boucicaut preserved the substantive demands rather than discarding them. "Provoke" means to incite or inflame, which is the opposite of the calming effect described.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20XKGRB', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Kelp forests along the coast of Tasmania have declined by more than 90 percent since the 1940s due to rising ocean temperatures. _______ marine ecologist Cayne Layton has begun cultivating heat-resistant kelp strains in laboratory tanks, hoping to eventually replant them in the wild.', $lyceon_json$[{"key":"A","text":"In response,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"In other words,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a problem (kelp forest decline) and then describes an action taken to address that problem (cultivating heat-resistant kelp). "In response," correctly signals that the second sentence is a reaction to the situation described in the first. "Similarly," incorrectly implies the second sentence describes a parallel or comparable phenomenon rather than a reactive measure. "In other words," incorrectly suggests the second sentence restates the first in different terms, but it introduces new information about a solution. "Granted," incorrectly introduces a concession, which does not fit the cause-and-response relationship between the sentences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW210BE3I', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the geochemist nor her three graduate students ______ able to replicate the high-pressure synthesis described in the 2017 paper, leading the team to suspect that an undisclosed catalytic agent had been used in the original experiment.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is being"}]$lyceon_json$::jsonb, 'B', NULL, E'With the correlative conjunction "neither...nor," the verb agrees with the nearer subject. Here the nearer subject is "her three graduate students," which is plural, so the plural past-tense form "were" is required. The sentence also describes a completed past event (the team subsequently suspected something), confirming the past tense. "Was" is singular and does not agree with the nearer plural subject. "Has been" is singular present perfect, failing on both number agreement and tense. "Is being" is singular present progressive, also incorrect in number and tense for this context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22H6YZX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made in the text?', E'Agricultural economist Tomoko Sakai has argued that vertical farming operations in urban centers will eventually replace conventional field agriculture as the primary source of leafy greens for metropolitan populations. Sakai points to the water efficiency of hydroponic systems, which use approximately 90 percent less water than traditional soil-based cultivation, and to the elimination of transportation costs when produce is grown within city limits. She concludes that these economic advantages will make vertical farms commercially dominant within fifteen years.', $lyceon_json$[{"key":"A","text":"The energy costs required to power artificial lighting in vertical farms have remained consistently high and currently account for over 60 percent of total operating expenses, offsetting savings from water efficiency and reduced transportation."},{"key":"B","text":"Consumer surveys indicate that a majority of urban residents prefer the taste of hydroponically grown lettuce to that of field-grown lettuce."},{"key":"C","text":"Several universities have recently established research programs focused on improving hydroponic nutrient delivery systems."},{"key":"D","text":"The global acreage devoted to conventional leafy green cultivation has decreased by 3 percent over the past decade."}]$lyceon_json$::jsonb, 'A', NULL, E'Sakai''s claim rests on the economic advantages of vertical farming—water savings and reduced transportation costs. The finding that energy costs for artificial lighting offset these savings directly undermines the economic argument that underpins her prediction of commercial dominance. Consumer preference for hydroponic lettuce would support rather than weaken demand for vertical farming. The establishment of university research programs on hydroponics is neutral to slightly supportive of vertical farming''s viability and does not challenge Sakai''s economic argument. The decrease in conventional leafy green acreage could be interpreted in multiple ways and does not directly address whether vertical farms'' economic advantages are sufficient for dominance—it might even seem to support the trend Sakai predicts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22W7OD0', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research study, if accurate, would most effectively support the literary critic''s interpretation described in the text?', E'Literary critic Amara Osei has proposed that the recurring imagery of enclosed gardens in the novels of nineteenth-century British author Charlotte Yonge functions not as a conventional symbol of feminine domesticity, as previous scholars have assumed, but rather as a representation of intellectual autonomy. Osei argues that Yonge''s garden spaces are consistently associated with moments when female characters engage in independent study, philosophical debate, or strategic decision-making—activities that transgress the domestic expectations of the Victorian period. Osei''s reading reframes the garden enclosure as a site of cognitive liberation rather than spatial confinement.', $lyceon_json$[{"key":"A","text":"\"In Yonge's The Daisy Chain, the walled garden at Stoneborough is the setting for Ethel May's self-directed study of classical Greek, an endeavor she pursues without her father's knowledge or approval.\""},{"key":"B","text":"\"Yonge's personal correspondence reveals that she maintained an extensive herb garden at her home in Otterbourne, which she tended daily as a form of physical recreation.\""},{"key":"C","text":"\"The enclosed garden appears in approximately 70 percent of Victorian novels published between 1840 and 1870, making it one of the most common settings in the period's fiction.\""},{"key":"D","text":"\"In The Heir of Redclyffe, Yonge describes the Morville estate's garden in elaborate botanical detail, cataloguing seventeen distinct species of flowering plants across three chapters.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Osei''s interpretation holds that Yonge''s garden imagery represents intellectual autonomy rather than domesticity, with garden spaces linked to independent study and transgressive intellectual activity. The quotation describing Ethel May''s self-directed Greek study in a walled garden—pursued without paternal approval—directly exemplifies the connection between enclosed gardens and autonomous intellectual pursuits that Osei identifies. The quotation about Yonge''s personal herb garden concerns the author''s biography rather than the literary function of gardens in her novels. The statistic about enclosed gardens appearing in 70 percent of Victorian novels addresses the prevalence of the setting across the genre, not its specific symbolic function in Yonge''s work. The quotation about elaborate botanical cataloguing in The Heir of Redclyffe describes detailed natural description but does not connect the garden space to intellectual autonomy or independent decision-making, supporting at most a reading of gardens as aesthetic settings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22YG9CB', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Musicologist Renata Volkov has examined the compositional notebooks of Czech composer Erwin Schulhoff, who was active in Prague during the 1920s and 1930s. Schulhoff''s notebooks reveal that he frequently sketched jazz-influenced rhythmic patterns alongside fragments of Moravian folk melodies, often on the same page. Yet in his published essays, Schulhoff consistently characterized his music as rooted exclusively in Central European folk traditions, making no mention of jazz. Volkov suggests that this discrepancy indicates that Schulhoff ________', $lyceon_json$[{"key":"A","text":"deliberately concealed one of his musical influences from the public, likely because jazz was viewed with suspicion by the Prague cultural establishment of that era."},{"key":"B","text":"abandoned jazz-influenced composition entirely after receiving negative reviews of his early orchestral works."},{"key":"C","text":"regarded Moravian folk melodies as inherently superior to jazz as a foundation for serious concert music."},{"key":"D","text":"incorporated jazz rhythms into his compositions accidentally, without being consciously aware of their origins."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes a clear discrepancy: Schulhoff privately worked with jazz patterns alongside folk melodies but publicly claimed only folk roots. The most logical inference from this gap between private practice and public statement is deliberate concealment, and the additional context about the cultural establishment provides a plausible motive. The claim that Schulhoff abandoned jazz entirely contradicts the evidence that jazz patterns appear throughout his notebooks. The suggestion that he viewed folk melodies as superior is unsupported—the passage shows him actively combining both traditions in his working process. The idea that he incorporated jazz accidentally despite deliberately sketching jazz patterns on the same pages as folk fragments is implausible given the intentional nature of compositional notebook work.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW237QYRU', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2019 study, neuroscientist Daniela Schiller demonstrated that memories are not static recordings but are reconstructed each time they are ______ her team found that reactivating a fearful memory while introducing new, non-threatening information could weaken the original fear response permanently.', $lyceon_json$[{"key":"A","text":"recalled;"},{"key":"B","text":"recalled,"},{"key":"C","text":"recalled, and"},{"key":"D","text":"recalled:"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses must be separated here: one about memories being reconstructed upon recall, and another about Schiller''s team finding that reactivating a fearful memory could weaken the fear response. A semicolon correctly joins two closely related independent clauses. A comma alone ("recalled,") creates a comma splice. The choice "recalled, and" is problematic because the second clause introduces a distinct finding with its own subject ("her team") and is not a coordinate predicate of the first clause; additionally, using a comma plus "and" after a subordinate clause ending ("each time they are recalled") misleadingly signals that the coordinated element is another subordinate clause rather than a new main clause. A colon ("recalled:") would be incorrect because the second clause does not explain, define, or elaborate on the word "recalled" — it introduces a separate experimental finding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26R77YY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'In a 2019 study of neural development in juvenile zebrafish, researchers at the University of Konstanz found that the animals'' brains remained remarkably plastic well into adolescence, forming and dissolving synaptic connections at rates three times higher than those observed in adult specimens. This extended window of neural reorganization, the team argued, helps explain why zebrafish can recover motor function after spinal injuries that would cause permanent paralysis in less adaptable species.', $lyceon_json$[{"key":"A","text":"synthetic"},{"key":"B","text":"superficial"},{"key":"C","text":"malleable"},{"key":"D","text":"durable"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes brains that form and dissolve connections at high rates and undergo "neural reorganization," indicating that "plastic" means malleable — capable of being reshaped. "Synthetic" refers to an artificial material, which contradicts the biological context of living neural tissue. "Superficial" means shallow or surface-level, which has no support in the passage''s discussion of deep structural brain changes. "Durable" means long-lasting and resistant to change, which is the opposite of the rapid reorganization described.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26RPK58', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Paleobotanist Miriam Hossain analyzed fossilized pollen samples extracted from a 47-million-year-old lake sediment core in what is now the Messel region of Germany. The samples revealed an unusually high concentration of pollen from Toddalia, a genus of thorny shrubs now found exclusively in tropical Africa and Southeast Asia. Alongside the Toddalia pollen, Hossain identified pollen from Fagus (beech) and Carpinus (hornbeam)—genera that today thrive in temperate forests with pronounced seasonal temperature variation. The co-occurrence of these tropical and temperate genera in the same sediment layer led Hossain to propose that the Messel ecosystem during this period ________', $lyceon_json$[{"key":"A","text":"supported a mixed flora combining tropical and temperate species, suggesting a climate regime without the sharp seasonal extremes that currently separate the ranges of these genera."},{"key":"B","text":"experienced rapid alternation between tropical and temperate climate conditions, with each phase lasting only a few thousand years before reversing."},{"key":"C","text":"was dominated by Toddalia shrubs, which had not yet evolved the temperature sensitivity that restricts them to tropical regions today."},{"key":"D","text":"contained an anomalous sediment composition that caused pollen from widely separated ecosystems to accumulate in a single deposit through water transport."}]$lyceon_json$::jsonb, 'A', NULL, E'The key evidence is the co-occurrence of tropical and temperate pollen in the same sediment layer. The most logical inference is that the Messel ecosystem simultaneously supported both plant types, implying a climate that lacked the sharp seasonal extremes that today prevent these genera from coexisting. This follows directly from the premise that both groups were growing in the same region at the same time. The proposal of rapid climate alternation is inconsistent with pollen from both groups appearing in the same sediment layer—if conditions alternated, the genera would not co-occur simultaneously. The claim that Toddalia had not yet evolved temperature sensitivity is speculative and unsupported, and it also ignores the temperate genera whose presence must also be explained. The suggestion of anomalous water transport depositing pollen from distant ecosystems undermines rather than explains the finding and contradicts the premise that Hossain drew a conclusion about the local ecosystem from the co-occurrence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
