INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ELJMHV', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'The Mpemba effect — the counterintuitive observation that hot water can freeze faster than cold water under certain conditions — has resisted definitive explanation since Tanzanian student Erasto Mpemba brought it to scientific attention in 1969. Proposed mechanisms have included faster evaporation reducing the mass of hot water, dissolved gas differences altering convection patterns, and supercooling thresholds varying with initial temperature.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ERB93B', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Kenji Furukawa studied the nesting behavior of sweat bees (Halictidae) in clay soils across three river valleys in central Japan. He found that colonies established in south-facing embankments consistently produced 35 percent more offspring per season than colonies in north-facing embankments. Because south-facing slopes in the Northern Hemisphere receive more direct sunlight and therefore maintain higher soil temperatures, Furukawa concluded that ________', $lyceon_json$[{"key":"A","text":"sweat bee reproductive success is positively influenced by the thermal conditions of their nesting sites."},{"key":"B","text":"sweat bees in central Japan face fewer predators on south-facing slopes than on north-facing slopes."},{"key":"C","text":"clay soils are the only substrate in which sweat bees can successfully construct nesting tunnels."},{"key":"D","text":"sweat bee populations in the Southern Hemisphere would show the opposite pattern, favoring north-facing slopes."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage links south-facing slopes to both higher soil temperatures and greater offspring production, then asks for the conclusion Furukawa drew. The inference that thermal conditions at nesting sites positively influence reproductive success follows directly from the stated evidence. The claim about fewer predators on south-facing slopes introduces a factor not mentioned in the passage and is unsupported by the evidence presented. The assertion that clay is the only viable substrate overgeneralizes far beyond the passage, which studies clay soils but never claims they are uniquely suitable. The prediction about Southern Hemisphere populations, while plausible, goes beyond the scope of the described research—Furukawa''s conclusion is about the relationship between temperature and reproduction, not about hemispheric predictions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F6YLZU', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1973, the sociologist Elijah Anderson began fieldwork in a neighborhood he called "Jelly''s," observing how residents navigated an economy shaped by deindustrialization. Anderson documented a pattern he termed "code-switching": residents adopted one set of behavioral norms when dealing with established community institutions and a different set when interacting with the informal street economy. He argued that this duality was not a sign of moral inconsistency but rather a pragmatic response to conflicting demands placed on individuals by two coexisting social systems.', $lyceon_json$[{"key":"A","text":"It presents a researcher's observation, describes a specific behavioral pattern he identified, and then offers his interpretation of that pattern."},{"key":"B","text":"It compares two competing theories about neighborhood decline and evaluates which one is better supported by evidence."},{"key":"C","text":"It traces the historical causes of deindustrialization and then examines their effects on a specific community."},{"key":"D","text":"It introduces a sociological term, defines it using multiple examples, and then critiques its limitations."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first introduces Anderson''s fieldwork (observation), then describes the code-switching pattern he identified (behavioral pattern), and finally presents his argument that this duality was pragmatic rather than morally inconsistent (interpretation). The choice about competing theories of neighborhood decline misreads the passage, which presents only Anderson''s perspective and does not compare rival theories. The choice about tracing historical causes of deindustrialization misidentifies the text''s purpose; deindustrialization is mentioned as context, not analyzed in its own right. The choice about defining a term and critiquing its limitations captures only part of the structure — the passage defines code-switching but does not critique the concept''s limitations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G3DUYY', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late Cretaceous period, the Western Interior Seaway divided North America into two landmasses, Laramidia and Appalachia. Paleontologists have traditionally attributed the high dinosaur diversity on Laramidia to geographic isolation created by this marine barrier. _______ a 2023 analysis of fossilized pollen and leaf morphology from both landmasses reveals that many plant species were shared across the seaway throughout its existence, suggesting that the barrier was periodically permeable and that other factors, such as latitudinal climate gradients, may better explain Laramidia''s exceptional species richness.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"That is,"},{"key":"C","text":"By comparison,"},{"key":"D","text":"Yet,"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage presents a traditional explanation (isolation via the seaway caused high diversity) and then introduces new evidence that undermines that explanation (plant species crossed the seaway, suggesting it was not a strict barrier). "Yet," correctly signals that the new evidence challenges or complicates the traditional view. "In addition," incorrectly implies the new analysis supplements the traditional explanation rather than challenging it. "That is," incorrectly implies the new analysis restates or clarifies the traditional view, but it actually introduces contrary evidence. "By comparison," incorrectly frames the relationship as a comparison between two parallel items, when the passage is presenting evidence against a prior claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HB40YH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The flamingos at Lake Natron in Tanzania, ______ high-alkaline waters deter most predators, build their nests from mounds of salt-crusted mud that harden in the equatorial sun.', $lyceon_json$[{"key":"A","text":"who's"},{"key":"B","text":"whose"},{"key":"C","text":"which"},{"key":"D","text":"where"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank introduces a nonrestrictive relative clause that modifies "Lake Natron" and requires a possessive relative pronoun, since the clause describes the lake''s waters: "whose high-alkaline waters deter most predators." The possessive relative pronoun "whose" correctly shows that the waters belong to the lake. "Who''s" is a contraction of "who is" or "who has," which produces the nonsensical reading "who is high-alkaline waters deter." "Which" lacks the possessive relationship needed — "which high-alkaline waters deter most predators" leaves the clause without a clear grammatical connection between the lake and its waters. "Where" would mean "in which," producing "where high-alkaline waters deter most predators" — while semantically close, this creates a clause in which "high-alkaline waters" appears without a possessive link to the antecedent, and the resulting sentence awkwardly nests an adverbial clause rather than providing the required possessive modification.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M0CIGD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'When cognitive scientist Lera Boroditsky examined how speakers of Kuuk Thaayorre, an Aboriginal Australian language, conceptualize time, she found that they consistently arranged temporal sequences from east to west rather than from left to right or right to left. Unlike English speakers, who default to a left-to-right timeline mirroring their writing system, Kuuk Thaayorre speakers oriented time according to cardinal directions, adjusting the arrangement based on which way they were facing. Boroditsky interpreted this as evidence that spatial frameworks embedded in language can fundamentally shape temporal cognition. Some critics, however, have cautioned that the east-to-west pattern might reflect cultural practices—such as tracking the sun''s movement—rather than a direct linguistic effect. Boroditsky has acknowledged this possibility but maintains that the consistency of the pattern across varied experimental settings, including tasks performed indoors without environmental cues, suggests that the linguistic encoding of space plays a structuring role that cannot be reduced to incidental cultural habit.', $lyceon_json$[{"key":"A","text":"Research on Kuuk Thaayorre speakers reveals an east-to-west temporal orientation that Boroditsky argues reflects a linguistic influence on cognition, though the relative contributions of language and culture remain debated."},{"key":"B","text":"Boroditsky has conclusively demonstrated that the Kuuk Thaayorre language causes its speakers to perceive time differently from English speakers."},{"key":"C","text":"Critics of Boroditsky's work have shown that the east-to-west temporal orientation of Kuuk Thaayorre speakers is best explained by their practice of tracking the sun's path."},{"key":"D","text":"The primary finding of Boroditsky's research is that writing systems determine how speakers of all languages conceptualize temporal sequences."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Boroditsky''s finding about Kuuk Thaayorre speakers'' east-to-west temporal arrangement, her interpretation that language shapes temporal cognition, and critics'' alternative explanation involving cultural practice, noting that the debate remains open. The choice acknowledging both the finding and the ongoing debate accurately captures the full scope of the text. The claim that Boroditsky conclusively demonstrated a causal link overstates the passage, which presents an ongoing debate rather than a settled conclusion. The assertion that critics have shown cultural practice to be the best explanation misrepresents their position—they offered a cautionary alternative, not a demonstrated finding. The suggestion that writing systems determine temporal conceptualization across all languages distorts the passage, which mentions English speakers'' left-to-right pattern as a contrast but never generalizes the claim to all languages or asserts that writing systems are the primary determinant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MOC53F', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologists studying the ancient city of Mohenjo-daro have long noted its remarkably uniform brick dimensions, suggesting centralized manufacturing standards across the Indus Valley civilization. _______ recent petrographic analyses of bricks from seventeen different sites reveal distinct mineral compositions, indicating that bricks were produced locally at each settlement rather than at a single centralized facility.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"However,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence describes an observation suggesting centralized manufacturing, while the second sentence presents evidence that bricks were actually produced locally, contradicting the initial suggestion. "However," correctly signals this contrast between the expected conclusion and the new evidence. "Furthermore," incorrectly implies the second sentence adds supporting information to the first, when it actually challenges it. "Consequently," incorrectly suggests local production is a result of uniform dimensions, which reverses the logical relationship. "Specifically," incorrectly implies the second sentence elaborates on the same point rather than contradicting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NC36GT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every autumn, the residents of Oaxaca, Mexico, celebrate the Night of the Radishes, a festival in which artisans ______ intricate sculptures from oversized radishes grown specifically for the event.', $lyceon_json$[{"key":"A","text":"carves"},{"key":"B","text":"carve"},{"key":"C","text":"has carved"},{"key":"D","text":"is carving"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the relative clause is "artisans," which is plural. The verb must agree with this plural subject in the simple present tense, matching the habitual action described by "every autumn." The plural present-tense form "carve" is correct. "Carves" is a singular present-tense form that does not agree with the plural subject. "Has carved" is singular present perfect, which disagrees in both number and tense. "Is carving" is singular present progressive, also failing to agree with the plural subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OL91L2', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the archaeologist had expected the excavation site near Tbilisi to yield only medieval artifacts, the team ______ fragments of pottery dating to the early Bronze Age beneath the lowest stratum of the dig.', $lyceon_json$[{"key":"A","text":"has uncovered"},{"key":"B","text":"uncovering"},{"key":"C","text":"uncovered"},{"key":"D","text":"will uncover"}]$lyceon_json$::jsonb, 'C', NULL, E'The subordinate clause uses the past perfect ("had expected"), establishing a past time frame. The main clause requires a finite verb in the simple past to describe what happened after or contrary to that expectation. "Uncovered" correctly provides a simple past tense verb. "Has uncovered" is present perfect, which conflicts with the established past time frame. "Uncovering" is a participle, not a finite verb, and would leave the main clause without a predicate. "Will uncover" is future tense, which is inconsistent with the past-tense narrative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PB7245', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Lera Boroditsky has demonstrated that speakers of Kuuk Thaayorre, an Aboriginal Australian language, orient spatial descriptions using cardinal directions rather than relative terms like "left" and "right." This linguistic practice correlates with superior spatial orientation abilities compared to speakers of languages that rely on egocentric reference frames. _______ Boroditsky cautions that these findings do not establish that language alone determines spatial cognition, since cultural practices such as long-distance navigation without instruments likely reinforce the same directional awareness that the language encodes.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"For instance,"},{"key":"D","text":"In contrast,"}]$lyceon_json$::jsonb, 'A', NULL, E'The first two sentences establish a correlation between language structure and spatial cognition, while the third sentence introduces a caveat: the correlation does not prove causation because cultural practices may independently contribute. "Nevertheless," correctly signals that the third sentence qualifies or tempers the preceding claim without fully rejecting it. "Moreover," incorrectly suggests the caution adds further support to the correlation claim, when it actually introduces a limitation. "For instance," incorrectly frames the caution as an illustrative example of the correlation, but the sentence is actually complicating the interpretation. "In contrast," is too strong because Boroditsky is not presenting an opposing finding but rather refining the interpretation of her own results.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q97MCG', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'Historian Camille Lefebvre''s 2021 study of nineteenth-century trade routes in the central Sahara challenges a long-standing assumption in African historiography: that trans-Saharan commerce declined precipitously after the abolition of the transatlantic slave trade. Lefebvre''s analysis of tax ledgers from Agadez, a caravan hub in present-day Niger, reveals that between 1850 and 1890, the volume of goods passing through the city actually increased by roughly 40 percent. This growth was driven not by human trafficking but by the expanding demand for leather, ostrich feathers, and natron salt in Mediterranean port cities. Lefebvre contends that scholars have conflated the decline of one specific commodity—enslaved people—with the decline of the entire trade network, thereby obscuring the commercial resilience of Saharan communities during this period.', $lyceon_json$[{"key":"A","text":"Lefebvre's research demonstrates that trans-Saharan trade actually grew in the late nineteenth century, contradicting the assumption that it declined after the end of the transatlantic slave trade."},{"key":"B","text":"The city of Agadez served as the single most important commercial hub in the entire trans-Saharan trade network during the nineteenth century."},{"key":"C","text":"Lefebvre argues that historians have paid insufficient attention to the role of natron salt in sustaining Saharan economies."},{"key":"D","text":"Trans-Saharan trade routes were primarily used for transporting luxury goods rather than essential commodities throughout the nineteenth century."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s central argument is that Lefebvre''s research overturns the conventional view that trans-Saharan trade declined after the abolition of the transatlantic slave trade, showing instead that trade volume grew significantly. The choice capturing this contradiction between the historical assumption and Lefebvre''s findings is the correct main idea. The claim that Agadez was the single most important hub overstates the passage, which identifies it as a caravan hub but never ranks it against others. The suggestion that Lefebvre''s argument centers on natron salt specifically misreads a supporting detail as the main point—salt is mentioned alongside leather and ostrich feathers as one of several commodities. The characterization of trans-Saharan routes as primarily for luxury goods distorts the passage, which lists both luxury items (ostrich feathers) and practical ones (salt) without making such a hierarchy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QICI62', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Voyager 1 spacecraft, launched in 1977, has traveled farther from Earth than any other human-made ______ continues to transmit scientific data back to researchers at NASA''s Jet Propulsion Laboratory.', $lyceon_json$[{"key":"A","text":"object, it"},{"key":"B","text":"object it"},{"key":"C","text":"object and it"},{"key":"D","text":"object; and it"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank joins two independent clauses: one about Voyager 1 having traveled farther than any other human-made object, and one about it continuing to transmit data. Using a comma alone between independent clauses ("object, it") creates a comma splice. Omitting all punctuation and conjunctions ("object it") creates a run-on sentence. Using a semicolon followed by a coordinating conjunction ("object; and it") is non-standard, since a semicolon replaces the conjunction rather than preceding one. The correct choice uses a coordinating conjunction with no comma before it in this structure, properly joining the clauses: "object and it."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RHIDR4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists Priya Mehta and Jonas Lindqvist hypothesized that the decline of gray wolf populations in northern Sweden has led to an increase in the browsing pressure exerted by moose on young birch trees. According to their hypothesis, the absence of wolves as apex predators allows moose populations to grow unchecked, resulting in heavier consumption of birch saplings and reduced forest regeneration in affected areas.', $lyceon_json$[{"key":"A","text":"Areas in northern Sweden where wolf populations have remained stable show significantly higher birch sapling survival rates than areas where wolves have declined."},{"key":"B","text":"Moose in northern Sweden have shifted their diet toward grasses and shrubs rather than birch saplings over the past two decades."},{"key":"C","text":"Gray wolf populations in southern Sweden have increased steadily since the introduction of conservation programs in the 1990s."},{"key":"D","text":"Birch trees in northern Sweden are more susceptible to fungal infections than birch trees in neighboring Finland."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that wolf decline causes increased moose browsing on birch saplings. A finding that areas with stable wolf populations have higher birch sapling survival directly supports the proposed causal chain by showing the expected contrast between wolf-present and wolf-absent areas. The finding about moose shifting toward grasses actually contradicts the hypothesis by suggesting moose are not consuming more birch. The observation about wolf recovery in southern Sweden addresses a different geographic region and does not speak to the relationship between wolves and birch sapling browsing in the north. The finding about fungal infections introduces an unrelated factor that does not bear on the predator-prey-vegetation dynamic described in the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
