INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WAXTCM', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2019, marine biologist Dara Orbach published findings on the anatomy of harbor porpoises in the waters near Denmark''s Kattegat Strait. Orbach''s team discovered that harbor porpoises in this region possess an unusually thick layer of blubber compared to populations in warmer Atlantic waters. The researchers attributed this difference primarily to the colder average water temperatures in the Kattegat, which hover around 7 degrees Celsius during winter months. The thicker blubber, Orbach argued, serves as critical thermal insulation, enabling these porpoises to maintain their core body temperature despite the harsh conditions.', $lyceon_json$[{"key":"A","text":"Harbor porpoises near Denmark's Kattegat Strait have adapted to cold water by developing thicker blubber than porpoises in warmer regions."},{"key":"B","text":"Dara Orbach's research methods represented a significant departure from previous approaches to studying marine mammal anatomy."},{"key":"C","text":"Harbor porpoises are better suited to cold-water environments than most other species of marine mammals."},{"key":"D","text":"The Kattegat Strait's winter temperatures create dangerous conditions for all marine mammals inhabiting the region."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the finding that harbor porpoises in the Kattegat Strait have thicker blubber than those in warmer waters, attributing this to colder temperatures. The choice stating that these porpoises adapted to cold water through thicker blubber accurately captures this central idea. The claim about Orbach''s research methods being a departure is not supported by the text, which describes findings rather than methodological innovation. The assertion that harbor porpoises are better suited to cold water than most other marine mammals goes beyond anything stated in the passage. Similarly, the suggestion that Kattegat winter temperatures are dangerous for all marine mammals overgeneralizes from the passage''s specific focus on one species'' adaptation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WDGUT6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "volatile" most nearly mean?', E'During the 1930s, the chemist Linus Pauling studied the behavior of certain carbon-based compounds that decomposed rapidly when exposed to slight temperature changes. Pauling described these substances as volatile, noting that their molecular bonds broke apart far more easily than those of comparable inorganic materials.', $lyceon_json$[{"key":"A","text":"unstable"},{"key":"B","text":"hostile"},{"key":"C","text":"expensive"},{"key":"D","text":"visible"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes substances that "decomposed rapidly" and whose "molecular bonds broke apart far more easily," indicating that "volatile" means unstable. "Hostile" implies aggression or antagonism, which has no connection to chemical decomposition. "Expensive" misreads the passage entirely, as cost is never mentioned. "Visible" relates to sight, which is irrelevant to the chemical behavior described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
