INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZC4DT3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Historian Marcia Chatelain''s research examines how fast-food franchises became engines of economic development in Black communities during the 1960s and ______ Chatelain argues, the relationship between these corporations and the neighborhoods they served was far more complicated than either celebration or condemnation would suggest.', $lyceon_json$[{"key":"A","text":"1970s, however,"},{"key":"B","text":"1970s; however,"},{"key":"C","text":"1970s however,"},{"key":"D","text":"1970s, however;"}]$lyceon_json$::jsonb, 'B', NULL, E'The text contains two independent clauses joined by the conjunctive adverb "however." When a conjunctive adverb connects two independent clauses, Standard English requires a semicolon before the adverb and a comma after it: "1970s; however, Chatelain argues..." Using only a comma before "however" ("1970s, however,") creates a comma splice between two independent clauses. Omitting the punctuation before "however" entirely ("1970s however,") produces a run-on sentence. Placing a semicolon after "however" instead of a comma ("1970s, however;") both creates a comma splice before the conjunctive adverb and misplaces the semicolon after it, violating standard punctuation conventions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
